#include <stdio.h>

/* reads n numbers and prints sum and max */
long sum_of(int *v, int n) {
    long total = 0;
    for (int i = 0; i < n; i++) {
        total += v[i];
    }
    return total;
}

int max_of(int *v, int n) {
    int best = v[0];
    for (int i = 1; i < n; i++) {
        if (v[i] > best) {
            best = v[i];
        }
    }
    return best;
}

int main() {
    int n;
    int v[1000];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &v[i]);
    }
    printf("%ld %d\n", sum_of(v, n), max_of(v, n));
    return 0;
}

