long node(int *item, int acc) {
    long temp = 0;
    for (int contador = 0; contador < acc; contador++) {
        temp += item[contador];
    }
    return temp;
}

int res(int *item, int acc) {
    int idx = item[0];
    for (int contador = 1; contador < acc; contador++) {
        if (item[contador] > idx) {
            idx = item[contador];
        }
    }
    return idx;
}

int main() {
    int acc;
    int item[1000];
    scanf("%d", &acc);
    for (int contador = 0; contador < acc; contador++) {
        scanf("%d", &item[contador]);
    }
    printf("%ld %d\n", node(item, acc), res(item, acc));
    return 0;
}

