void ler(int *vetor, int tamanho) {
    int i;
    for (i = 0; i < tamanho; i++)
        scanf("%d", vetor + i);
}

void calcular(int *vetor, int tamanho, long *soma, int *maior) {
    int i;
    *soma = 0;
    *maior = vetor[0];
    for (i = 0; i < tamanho; i++) {
        *soma = *soma + vetor[i];
        if (vetor[i] > *maior)
            *maior = vetor[i];
    }
}

int main(void) {
    int tamanho, maior;
    long soma;
    scanf("%d", &tamanho);
    int *vetor = malloc(sizeof(int) * tamanho);
    ler(vetor, tamanho);
    calcular(vetor, tamanho, &soma, &maior);
    printf("%ld %d\n", soma, maior);
    free(vetor);
    return 0;
}

