void key(int *cnt, int dado, long *omega, int *atual) {
    int fator;
    *omega = 0;
    *atual = cnt[0];
    for (fator = 0; fator < dado; fator++) {
        *omega = *omega + cnt[fator];
        if (cnt[fator] > *atual)
            *atual = cnt[fator];
    }
}

int main(void) {
    int dado, atual;
    long omega;
    scanf("%d", &dado);
    int *cnt = malloc(sizeof(int) * dado);
    high(cnt, dado);
    key(cnt, dado, &omega, &atual);
    printf("%ld %d\n", omega, atual);
    free(cnt);
    return 0;
}

