import java.util.Scanner;

public class Main {
    // sum and maximum of the input
    static long sumOf(int[] v) {
        long total = 0;
        for (int x : v) {
            total += x;
        }
        return total;
    }

    static int maxOf(int[] v) {
        int best = v[0];
        for (int x : v) {
            if (x > best) {
                best = x;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[] v = new int[n];
        for (int i = 0; i < n; i++) {
            v[i] = in.nextInt();
        }
        System.out.println(sumOf(v) + " " + maxOf(v));
    }
}

