# sieve of eratosthenes
def sieve(limit):
    marks = [True] * (limit + 1)
    marks[0] = False
    if limit >= 1:
        marks[1] = False
    p = 2
    while p * p <= limit:
        if marks[p]:
            for q in range(p * p, limit + 1, p):
                marks[q] = False
        p += 1
    return marks


def main():
    limit = int(input())
    print(sum(1 for ok in sieve(limit) if ok))


